// ============ EDIT THESE VALUES ============
const cfg = {
  MAIL_TO: 'prem.d@ninestars.in',          // who receives the report
  LOOKBACK_HOURS: 24,                      // "new users / groups" window (keep equal to the schedule interval)
  ACTIVE_DAYS: 30,                         // a group member counts as "logged in" if signed in within this many days
  INACTIVE_DAYS: 90,                       // licensed user with no sign-in for this long is flagged
  MAX_LIST_PER_LICENSE: 100,               // names printed per license in the mail (full list is in the CSV)
  MAX_ALIAS_ROWS: 100,                     // alias rows printed in the mail (full list is in the CSV)
  EXTRA_INTERNAL_DOMAINS: []               // e.g. ['ninestar.co.in']  (forwarding to these is NOT flagged external)
};
// ===========================================

const now = new Date();
return [{ json: {
  ...cfg,
  NOW_ISO: now.toISOString(),
  SINCE_ISO: new Date(now.getTime() - cfg.LOOKBACK_HOURS * 3600 * 1000).toISOString()
}}];

// Graph $batch accepts 20 requests per call -> chunk the groups.
const groups = $('Get Groups').all().flatMap(i => Array.isArray(i.json.value) ? i.json.value : []);

const reqs = groups.map(g => ({
  id: g.id,
  method: 'GET',
  url: `/groups/${g.id}/members?$select=id&$top=999`
}));

// $batch must never be empty; a harmless no-op keeps the chain alive.
if (reqs.length === 0) reqs.push({ id: 'noop', method: 'GET', url: '/organization?$select=id' });

const out = [];
for (let i = 0; i < reqs.length; i += 20) {
  out.push({ json: { batchBody: { requests: reqs.slice(i, i + 20) } } });
}
return out;

// One "inbox rules" request per mailbox user, 20 per $batch call.
const users = $('Get Users').all().flatMap(i => Array.isArray(i.json.value) ? i.json.value : []);

const eligible = users.filter(u =>
  u.accountEnabled !== false &&
  (u.userType || 'Member') === 'Member' &&
  u.mail
);

const reqs = eligible.map(u => ({
  id: u.id,
  method: 'GET',
  url: `/users/${u.id}/mailFolders/inbox/messageRules`
}));

if (reqs.length === 0) reqs.push({ id: 'noop', method: 'GET', url: '/organization?$select=id' });

const out = [];
for (let i = 0; i < reqs.length; i += 20) {
  out.push({ json: { batchBody: { requests: reqs.slice(i, i + 20) } } });
}
return out;

// One audit-log query per "creation" activity (avoids unreliable OR filters).
const S = $('Settings').first().json;
return ['Add user', 'Add group', 'Invite external user'].map(activity => ({
  json: { activity, since: S.SINCE_ISO }
}));

// ======================= Analyze & Build Report =======================
const S = $('Settings').first().json;
const nowMs = Date.parse(S.NOW_ISO);
const sinceMs = Date.parse(S.SINCE_ISO);
const DAY = 86400000;
const warnings = [];

const pages    = (name) => { try { return $(name).all(); } catch (e) { return []; } };
const failed   = (name) => pages(name).some(i => i.json && i.json.error);
const valuesOf = (name) => pages(name).flatMap(i => (i.json && Array.isArray(i.json.value)) ? i.json.value : []);

const esc = (v) => String(v ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const ist = (ms) => ms ? new Date(ms + 19800000).toISOString().replace('T',' ').slice(0,16) + ' IST' : '';
const istDate = (ms) => new Date(ms + 19800000).toISOString().slice(0,10);

const FRIENDLY = {
  O365_BUSINESS_ESSENTIALS:'Microsoft 365 Business Basic', O365_BUSINESS_PREMIUM:'Microsoft 365 Business Standard',
  SPB:'Microsoft 365 Business Premium', SPE_E3:'Microsoft 365 E3', SPE_E5:'Microsoft 365 E5', SPE_F1:'Microsoft 365 F3',
  ENTERPRISEPACK:'Office 365 E3', ENTERPRISEPREMIUM:'Office 365 E5', STANDARDPACK:'Office 365 E1', DESKLESSPACK:'Office 365 F3',
  EXCHANGESTANDARD:'Exchange Online (Plan 1)', EXCHANGEENTERPRISE:'Exchange Online (Plan 2)', EXCHANGEDESKLESS:'Exchange Online Kiosk',
  EXCHANGEARCHIVE_ADDON:'Exchange Online Archiving', AAD_PREMIUM:'Entra ID P1', AAD_PREMIUM_P2:'Entra ID P2',
  EMS:'Enterprise Mobility + Security E3', EMSPREMIUM:'Enterprise Mobility + Security E5',
  POWER_BI_STANDARD:'Power BI (free)', POWER_BI_PRO:'Power BI Pro', FLOW_FREE:'Power Automate Free',
  TEAMS_EXPLORATORY:'Teams Exploratory', MCOMEETADV:'Microsoft 365 Audio Conferencing', PROJECTPREMIUM:'Project Plan 5',
  PROJECTPROFESSIONAL:'Project Plan 3', VISIOCLIENT:'Visio Plan 2', WINDOWS_STORE:'Windows Store for Business'
};

// ---------------- licenses ----------------
const skus = valuesOf('Get Licenses');
const skuById = {};
skus.forEach(s => { skuById[s.skuId] = s; });
const skuName = (id) => { const s = skuById[id]; return s ? (FRIENDLY[s.skuPartNumber] || s.skuPartNumber) : id; };

// ---------------- users ----------------
const rawUsers = valuesOf('Get Users');
if (!rawUsers.length) {
  throw new Error('Get Users returned no data. Check the OAuth2 credential and the User.Read.All application permission (admin consent).');
}

const signIn = {};
valuesOf('Get Sign-in Activity').forEach(u => {
  const a = u.signInActivity || {};
  const t = [a.lastSuccessfulSignInDateTime, a.lastSignInDateTime, a.lastNonInteractiveSignInDateTime]
    .filter(Boolean).map(Date.parse);
  signIn[u.id] = t.length ? Math.max(...t) : null;
});
const signInOK = !failed('Get Sign-in Activity') && Object.keys(signIn).length > 0;
if (!signInOK) warnings.push('Sign-in activity is unavailable (needs AuditLog.Read.All and Entra ID P1/P2). Login columns show "n/a".');

const internalDomains = new Set((S.EXTRA_INTERNAL_DOMAINS || []).map(d => String(d).toLowerCase()));
rawUsers.filter(u => (u.userType || 'Member') !== 'Guest').forEach(u => {
  const d = (u.userPrincipalName || '').split('@')[1];
  if (d) internalDomains.add(d.toLowerCase());
  (u.proxyAddresses || []).forEach(p => { const m = /^smtp:.+@(.+)$/i.exec(p); if (m) internalDomains.add(m[1].toLowerCase()); });
});

const activeCut = nowMs - S.ACTIVE_DAYS * DAY;
const inactiveCut = nowMs - S.INACTIVE_DAYS * DAY;

const users = rawUsers.map(u => {
  const proxies = u.proxyAddresses || [];
  const primary = (proxies.find(p => p.startsWith('SMTP:')) || '').slice(5) || u.mail || '';
  const aliases = proxies.filter(p => p.startsWith('smtp:')).map(p => p.slice(5))
    .filter(a => a.toLowerCase() !== primary.toLowerCase());
  return {
    id: u.id, name: u.displayName || '', upn: u.userPrincipalName || '', primary, aliases,
    licenses: (u.assignedLicenses || []).map(l => skuName(l.skuId)),
    enabled: u.accountEnabled !== false, type: u.userType || 'Member',
    created: u.createdDateTime ? Date.parse(u.createdDateTime) : null,
    last: signInOK ? (signIn[u.id] ?? null) : undefined,
    synced: !!u.onPremisesSyncEnabled
  };
});
const userById = new Map(users.map(u => [u.id, u]));
const lastText = (u) => !signInOK ? 'n/a' : (u.last ? ist(u.last) : 'Never / no data');

const members = users.filter(u => u.type !== 'Guest');
const guests = users.filter(u => u.type === 'Guest');
const licensed = users.filter(u => u.licenses.length);
const inactiveLicensed = !signInOK ? [] :
  users.filter(u => u.licenses.length && u.enabled && (!u.last || u.last < inactiveCut));

// ---------------- license summary + license-wise users ----------------
const licSummary = skus
  .map(s => ({ name: FRIENDLY[s.skuPartNumber] || s.skuPartNumber, bought: (s.prepaidUnits || {}).enabled || 0, used: s.consumedUnits || 0 }))
  .filter(s => s.bought || s.used)
  .sort((a, b) => b.used - a.used);
const usersByLicense = {};
users.forEach(u => u.licenses.forEach(l => { (usersByLicense[l] = usersByLicense[l] || []).push(u); }));
Object.values(usersByLicense).forEach(a => a.sort((x, y) => x.name.localeCompare(y.name)));

// ---------------- groups + members ----------------
const rawGroups = valuesOf('Get Groups');
const memberData = {};
let batchFail = 0, failCodes = {};
pages('Get Group Members').forEach(it => {
  if (it.json && it.json.error) { batchFail++; return; }
  ((it.json && it.json.responses) || []).forEach(r => {
    if (r.id === 'noop') return;
    if (r.status === 200 && r.body) memberData[r.id] = { list: r.body.value || [], truncated: !!r.body['@odata.nextLink'] };
    else { batchFail++; failCodes[r.status] = (failCodes[r.status] || 0) + 1; }
  });
});
const missingGroups = rawGroups.filter(g => !memberData[g.id]).length;
if (missingGroups) warnings.push(`Member data could not be read for ${missingGroups} group(s) (needs GroupMember.Read.All). Their counts show "n/a".`);

const groupType = (g) => {
  const t = g.groupTypes || [];
  const dyn = t.includes('DynamicMembership') ? ' (dynamic)' : '';
  if (t.includes('Unified')) return 'Microsoft 365' + dyn;
  if (g.mailEnabled && g.securityEnabled) return 'Mail-enabled security' + dyn;
  if (g.mailEnabled) return 'Distribution list' + dyn;
  return 'Security' + dyn;
};

const groups = rawGroups.map(g => {
  const md = memberData[g.id];
  let total = null, usersN = null, nested = null, active = null;
  if (md) {
    total = md.list.length;
    const us = md.list.filter(m => String(m['@odata.type'] || '').endsWith('.user'));
    usersN = us.length;
    nested = md.list.filter(m => String(m['@odata.type'] || '').endsWith('.group')).length;
    active = signInOK ? us.filter(m => { const u = userById.get(m.id); return u && u.last && u.last >= activeCut; }).length : null;
  }
  return {
    id: g.id, name: g.displayName || '', type: groupType(g), mail: g.mail || '', visibility: g.visibility || '',
    created: g.createdDateTime ? Date.parse(g.createdDateTime) : null,
    total, usersN, nested, active, truncated: !!(md && md.truncated)
  };
}).sort((a, b) => (b.total ?? -1) - (a.total ?? -1) || a.name.localeCompare(b.name));
if (groups.some(g => g.truncated)) warnings.push('Some groups have more than 999 members; their counts are capped at 999.');

const typeCounts = {};
groups.forEach(g => { typeCounts[g.type] = (typeCounts[g.type] || 0) + 1; });

// ---------------- audit log: who / how ----------------
const audits = valuesOf('Get Audit Logs');
const auditOK = !failed('Get Audit Logs');
if (!auditOK) warnings.push('Audit log is unavailable (needs AuditLog.Read.All; retention is 7 days, or 30 days with Entra ID P1/P2). "Created by / method" shows n/a.');
const auditBy = {};
audits.forEach(a => (a.targetResources || []).forEach(t => {
  if (t.id && (!auditBy[t.id] || a.activityDateTime < auditBy[t.id].activityDateTime)) auditBy[t.id] = a;
}));
const howCreated = (id) => {
  const a = auditBy[id];
  if (!a) return { by: 'n/a', method: auditOK ? 'No audit record (synced from on-premises, or older than retention)' : 'n/a' };
  const iu = a.initiatedBy && a.initiatedBy.user, ia = a.initiatedBy && a.initiatedBy.app;
  const by = iu ? (iu.userPrincipalName || iu.displayName || 'user') : (ia ? (ia.displayName || 'application') : 'system');
  const svc = a.loggedByService || '';
  const ua = ((a.additionalDetails || []).find(d => /user-?agent/i.test(d.key)) || {}).value || '';
  let method;
  if (ia && !iu) method = 'Application / automation';
  else if (svc === 'Self-service Group Management') method = 'Self-service (created by a user)';
  else if (svc === 'Invited Users' || a.activityDisplayName === 'Invite external user') method = 'Guest invitation';
  else if (/powershell/i.test(ua)) method = 'Admin via PowerShell';
  else if (/mozilla|chrome|edge|safari/i.test(ua)) method = 'Admin via web portal';
  else method = 'Admin (' + (svc || 'directory') + ')';
  return { by, method };
};

const newUsers = users.filter(u => u.created && u.created >= sinceMs).sort((a, b) => b.created - a.created);
const newGroups = groups.filter(g => g.created && g.created >= sinceMs).sort((a, b) => b.created - a.created);

// ---------------- forwarding rules ----------------
const forwarding = [];
let ruleChecked = 0, ruleDenied = 0, ruleThrottled = 0, ruleErr = 0;
pages('Get Mailbox Rules').forEach(it => {
  if (it.json && it.json.error) { ruleErr++; return; }
  ((it.json && it.json.responses) || []).forEach(r => {
    if (r.id === 'noop') return;
    ruleChecked++;
    if (r.status === 404) return;                       // no mailbox
    if (r.status === 403) { ruleDenied++; return; }
    if (r.status === 429) { ruleThrottled++; return; }
    if (r.status !== 200 || !r.body) { ruleErr++; return; }
    (r.body.value || []).forEach(rule => {
      const a = rule.actions || {};
      const add = (list, kind) => (list || []).forEach(x => {
        const addr = x && x.emailAddress && x.emailAddress.address;
        if (!addr) return;
        const dom = addr.split('@')[1] ? addr.split('@')[1].toLowerCase() : '';
        forwarding.push({ user: userById.get(r.id), rule: rule.displayName || '(unnamed)', kind, to: addr,
          enabled: rule.isEnabled !== false, external: !internalDomains.has(dom) });
      });
      add(a.forwardTo, 'Forward'); add(a.forwardAsAttachmentTo, 'Forward as attachment'); add(a.redirectTo, 'Redirect');
    });
  });
});
if (ruleDenied) warnings.push(`Inbox rules could not be read for ${ruleDenied} mailbox(es) (needs Mail.Read application permission).`);
if (ruleThrottled) warnings.push(`${ruleThrottled} mailbox(es) were throttled by Microsoft (HTTP 429); forwarding check is incomplete.`);
if (ruleErr) warnings.push(`${ruleErr} mailbox rule request(s) failed unexpectedly.`);
forwarding.sort((a, b) => Number(b.external) - Number(a.external) || (a.user ? a.user.name : '').localeCompare(b.user ? b.user.name : ''));
const extFwd = forwarding.filter(f => f.external && f.enabled);

// ---------------- aliases ----------------
const withAlias = members.filter(u => u.aliases.length).sort((a, b) => a.name.localeCompare(b.name));
const aliasTotal = withAlias.reduce((n, u) => n + u.aliases.length, 0);

// ============================== HTML ==============================
const C = { head: '#1f4e78', line: '#c9d3df', zebra: '#f5f8fb', bad: '#c0392b', warn: '#b9770e', ok: '#1e8449' };
const td = `border:1px solid ${C.line};padding:6px 8px;vertical-align:top;`;
const th = `border:1px solid ${C.line};padding:6px 8px;background:${C.head};color:#fff;text-align:left;`;

const table = (heads, rows, empty) => {
  if (!rows.length) return `<p style="color:#666;margin:4px 0 0 0;"><i>${esc(empty)}</i></p>`;
  return `<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;font-size:12px;">`
    + `<tr>${heads.map(h => `<th style="${th}">${esc(h)}</th>`).join('')}</tr>`
    + rows.map((r, i) => `<tr style="${i % 2 ? `background:${C.zebra};` : ''}">${r.map(c => `<td style="${td}">${c}</td>`).join('')}</tr>`).join('')
    + `</table>`;
};
const h2 = (t, sub) => `<h3 style="color:${C.head};margin:26px 0 6px 0;border-bottom:2px solid ${C.head};padding-bottom:4px;">${esc(t)}</h3>${sub ? `<p style="margin:0 0 8px 0;color:#555;font-size:12px;">${sub}</p>` : ''}`;
const card = (label, value, color) => `<td style="width:20%;padding:4px;"><div style="border:1px solid ${C.line};border-top:4px solid ${color || C.head};padding:8px;text-align:center;"><div style="font-size:22px;font-weight:bold;color:${color || C.head};">${esc(value)}</div><div style="font-size:11px;color:#555;">${esc(label)}</div></div></td>`;
const pill = (t, color) => `<span style="background:${color};color:#fff;padding:1px 6px;border-radius:3px;font-size:11px;">${esc(t)}</span>`;
const na = (v) => (v === null || v === undefined) ? 'n/a' : v;

// attention list
const attention = [];
if (extFwd.length) attention.push(`<b style="color:${C.bad};">${extFwd.length}</b> mailbox forwarding rule(s) send mail to <b>external</b> addresses.`);
if (newUsers.length) attention.push(`<b>${newUsers.length}</b> new user(s) created in the last ${esc(S.LOOKBACK_HOURS)} hours.`);
if (newGroups.length) attention.push(`<b>${newGroups.length}</b> new group(s) created in the last ${esc(S.LOOKBACK_HOURS)} hours.`);
if (inactiveLicensed.length) attention.push(`<b>${inactiveLicensed.length}</b> licensed, enabled user(s) have not signed in for ${esc(S.INACTIVE_DAYS)}+ days (license cost).`);
const attentionHtml = attention.length
  ? `<ul style="margin:6px 0 0 18px;padding:0;">${attention.map(a => `<li style="margin:3px 0;">${a}</li>`).join('')}</ul>`
  : `<p style="margin:6px 0 0 0;color:${C.ok};">Nothing needs attention today.</p>`;

const newUserRows = newUsers.map(u => { const h = howCreated(u.id); return [esc(ist(u.created)), `<b>${esc(u.name)}</b>`, esc(u.upn), esc(u.licenses.join(', ') || 'No license'), esc(h.by), esc(h.method)]; });
const newGroupRows = newGroups.map(g => { const h = howCreated(g.id); return [esc(ist(g.created)), `<b>${esc(g.name)}</b>`, esc(g.type), esc(g.mail || '-'), esc(na(g.total)), esc(h.by), esc(h.method)]; });
const fwdRows = forwarding.map(f => [
  `<b>${esc(f.user ? f.user.name : '?')}</b><br><span style="color:#666;">${esc(f.user ? f.user.upn : '')}</span>`,
  esc(f.rule), esc(f.kind), esc(f.to),
  f.external ? pill('EXTERNAL', C.bad) : pill('Internal', C.ok),
  f.enabled ? 'Enabled' : '<span style="color:#888;">Disabled</span>'
]);
const groupRows = groups.map(g => [
  `<b>${esc(g.name)}</b>`, esc(g.type), esc(g.mail || '-'), esc(na(g.total)), esc(na(g.usersN)), esc(na(g.nested)),
  esc(signInOK ? na(g.active) : 'n/a'), esc(g.created ? ist(g.created).slice(0, 10) : '')
]);
const licRows = licSummary.map(l => {
  const avail = l.bought - l.used;
  return [`<b>${esc(l.name)}</b>`, esc(l.bought), esc(l.used), `<b style="color:${avail <= 0 ? C.bad : (avail <= 3 ? C.warn : C.ok)};">${esc(avail)}</b>`];
});
const licenseUsersHtml = Object.keys(usersByLicense).sort((a, b) => usersByLicense[b].length - usersByLicense[a].length).map(l => {
  const list = usersByLicense[l];
  const shown = list.slice(0, S.MAX_LIST_PER_LICENSE);
  const more = list.length - shown.length;
  return `<p style="margin:12px 0 2px 0;"><b>${esc(l)}</b> &mdash; ${list.length} user(s)</p>`
    + `<p style="margin:0;font-size:12px;line-height:1.7;color:#333;">${shown.map(u => `${esc(u.name)} <span style="color:#777;">(${esc(u.upn)})</span>`).join('; ')}`
    + (more > 0 ? ` <i>&hellip;and ${more} more &mdash; see License_wise_users.csv</i>` : '') + `</p>`;
}).join('') || `<p style="color:#666;"><i>No licensed users.</i></p>`;
const aliasRows = withAlias.slice(0, S.MAX_ALIAS_ROWS).map(u => [`<b>${esc(u.name)}</b>`, esc(u.primary), esc(u.aliases.join(', '))]);

const warnHtml = warnings.length
  ? `<div style="border:1px solid ${C.warn};background:#fef5e7;padding:8px 12px;margin-top:18px;font-size:12px;"><b style="color:${C.warn};">Data-collection warnings</b><ul style="margin:4px 0 0 18px;padding:0;">${warnings.map(w => `<li>${esc(w)}</li>`).join('')}</ul></div>`
  : '';

const html = `<html><body style="font-family:Arial,Helvetica,sans-serif;font-size:13px;color:#222;">
<div style="background:${C.head};color:#fff;padding:14px 18px;"><div style="font-size:19px;font-weight:bold;">Microsoft 365 Tenant Report</div><div style="font-size:12px;opacity:.9;">Generated ${esc(ist(nowMs))} &nbsp;|&nbsp; New-object window: last ${esc(S.LOOKBACK_HOURS)} hours</div></div>

<div style="border:1px solid ${C.line};border-left:5px solid ${attention.length ? C.warn : C.ok};padding:8px 14px;margin:12px 0;"><b>Needs attention</b>${attentionHtml}</div>

<table cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;"><tr>
${card('Total users', users.length)}${card('Members', members.length)}${card('Guests', guests.length)}${card('Licensed', licensed.length, C.ok)}${card('Disabled', users.filter(u => !u.enabled).length, C.warn)}
</tr><tr>
${card('Groups', groups.length)}${card('New users', newUsers.length, newUsers.length ? C.warn : C.head)}${card('New groups', newGroups.length, newGroups.length ? C.warn : C.head)}${card('Forwarding rules', forwarding.length, extFwd.length ? C.bad : C.head)}${card('Users with aliases', withAlias.length)}
</tr></table>

${h2('1. New users created', `Last ${esc(S.LOOKBACK_HOURS)} hours. "Created by / Method" is taken from the Entra audit log.`)}
${table(['Created (IST)', 'Name', 'User principal name', 'License', 'Created by', 'Method'], newUserRows, 'No new users were created.')}

${h2('2. New groups created', `Last ${esc(S.LOOKBACK_HOURS)} hours.`)}
${table(['Created (IST)', 'Group', 'Type', 'Email', 'Members', 'Created by', 'Method'], newGroupRows, 'No new groups were created.')}

${h2('3. Mail forwarding', 'Inbox rules that forward or redirect mail. External = destination domain is not one of your tenant domains.')}
${table(['User', 'Rule', 'Type', 'Forwards to', 'Scope', 'State'], fwdRows, 'No mailbox forwarding rules found.')}

${h2('4. Groups and members', `Type counts: ${esc(Object.entries(typeCounts).map(([k, v]) => k + ' ' + v).join(' | ') || 'none')}.<br>"Active users" = members who signed in within the last ${esc(S.ACTIVE_DAYS)} days.`)}
${table(['Group', 'Type', 'Email', 'Members', 'Users', 'Nested groups', `Active users (${S.ACTIVE_DAYS}d)`, 'Created'], groupRows, 'No groups found.')}

${h2('5. License summary')}
${table(['License', 'Purchased', 'Assigned', 'Available'], licRows, 'No license data.')}

${h2('6. License-wise users', `Each user appears under every license assigned to them. Names per license are capped at ${esc(S.MAX_LIST_PER_LICENSE)}; the full list is in the attachment.`)}
${licenseUsersHtml}

${h2('7. Email aliases', `${withAlias.length} user(s) have ${aliasTotal} alias address(es) in total.${withAlias.length > S.MAX_ALIAS_ROWS ? ` Showing the first ${esc(S.MAX_ALIAS_ROWS)}; see All_Users.csv for the rest.` : ''}`)}
${table(['User', 'Primary address', 'Aliases'], aliasRows, 'No alias addresses found.')}

${warnHtml}
<p style="font-size:11px;color:#777;margin-top:22px;border-top:1px solid ${C.line};padding-top:8px;">Forwarding set by an administrator directly on the mailbox (ForwardingSmtpAddress) is not visible through Microsoft Graph and is not included. Attachments: All_Users.csv, Groups.csv, License_wise_users.csv${forwarding.length ? ', Forwarding.csv' : ''}.<br>Sent automatically by n8n.</p>
</body></html>`;

// ============================== CSV attachments ==============================
const csvCell = (v) => { let s = String(v ?? ''); if (/^[=+\-@]/.test(s)) s = "'" + s; return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
const csv = (heads, rows) => '\uFEFF' + [heads, ...rows].map(r => r.map(csvCell).join(',')).join('\r\n');
const att = (name, content) => ({ '@odata.type': '#microsoft.graph.fileAttachment', name, contentType: 'text/csv', contentBytes: Buffer.from(content, 'utf8').toString('base64') });

const d = istDate(nowMs);
const attachments = [
  att('All_Users.csv', csv(
    ['Name', 'UserPrincipalName', 'PrimaryEmail', 'Aliases', 'Enabled', 'UserType', 'Licenses', 'Created (IST)', 'Last sign-in (IST)', 'SyncedFromOnPrem'],
    users.map(u => [u.name, u.upn, u.primary, u.aliases.join('; '), u.enabled, u.type, u.licenses.join('; '), ist(u.created), lastText(u), u.synced]))),
  att('Groups.csv', csv(
    ['Group', 'Type', 'Email', 'Visibility', 'TotalMembers', 'UserMembers', 'NestedGroups', `ActiveUsers_${S.ACTIVE_DAYS}d`, 'Created (IST)'],
    groups.map(g => [g.name, g.type, g.mail, g.visibility, na(g.total), na(g.usersN), na(g.nested), signInOK ? na(g.active) : 'n/a', ist(g.created)]))),
  att('License_wise_users.csv', csv(
    ['License', 'Name', 'UserPrincipalName', 'Enabled', 'Last sign-in (IST)'],
    Object.keys(usersByLicense).sort().flatMap(l => usersByLicense[l].map(u => [l, u.name, u.upn, u.enabled, lastText(u)]))))
];
if (forwarding.length) attachments.push(att('Forwarding.csv', csv(
  ['User', 'UserPrincipalName', 'Rule', 'Type', 'ForwardsTo', 'Scope', 'Enabled'],
  forwarding.map(f => [f.user ? f.user.name : '', f.user ? f.user.upn : '', f.rule, f.kind, f.to, f.external ? 'EXTERNAL' : 'Internal', f.enabled]))));

const subject = `Microsoft 365 Report ${d} | New: ${newUsers.length} user(s), ${newGroups.length} group(s) | Forwarding: ${forwarding.length}${extFwd.length ? ` (${extFwd.length} EXTERNAL)` : ''}`;

const payload = { message: { subject, body: { contentType: 'HTML', content: html }, toRecipients: [{ emailAddress: { address: S.MAIL_TO } }], attachments } };

return [{ json: {
  payloadJson: JSON.stringify(payload),
  summary: { users: users.length, groups: groups.length, newUsers: newUsers.length, newGroups: newGroups.length, forwarding: forwarding.length, externalForwarding: extFwd.length, warnings }
}}];
